function fig=fusiLightSuiteLandmarkHelp
% Nonmodal instructions can remain next to the annotation workspace.
fig=figure('Name','LightSuite | How to place matched landmarks','NumberTitle','off', ...
    'MenuBar','none','ToolBar','none','Color',[.035 .045 .045],'Position',[180 90 830 780]);
headings={'1  Find a recognizable feature','2  Navigate the two volumes independently', ...
    '3  Make one matched pair','4  Spread pairs through the whole acquired volume', ...
    '5  Inspect and correct','6  Save, fit and review'};
bodies={ ...
    'The left image is your median Doppler anatomy; the right image is a vascular reference atlas. Look for the same distinctive vessel bifurcation, vessel junction or consistent anatomical boundary in both images. These are anatomical correspondences, not Target/Control activation ROIs. Avoid arbitrary bright pixels.', ...
    'Choose coronal/AP, horizontal/DV or sagittal/ML views. Use the slider, arrows or slice-number field under EACH image. Slice numbers need not match: the sample and atlas have different voxel sizes, dimensions and coverage. The mouse wheel acts on the image under the pointer.', ...
    'Choose Mark matching points. Click the feature in YOUR SAMPLE first: a yellow + marks the pending point. Navigate the atlas to the same feature and click it. Both locations now share a pair number. Esc cancels the pending point; it is never saved as an unmatched landmark.', ...
    'Use both hemispheres and different AP, DV and ML positions. Five noncoplanar pairs are only a numerical minimum; several well-distributed, reliable pairs are preferable. Points in one plane cannot constrain a full 3D transform. Do not force a match outside acquired coverage.', ...
    'Right-click over either image in Mark mode to undo the last click: undoing an atlas point keeps its sample pending for correction; another right-click cancels that sample. Delete selected pair removes both points. Zoom and pan keep their normal mouse controls.', ...
    'Save pairs (S) saves and keeps editing. In guided mode, the green Save + continue button saves and starts fitting. READY / BUSY shows the current action; UNSAVED / SAVED with a time shows disk state. Review all fitted overlays before accepting. Fitted projects open read-only.'};
for k=1:6
    y=.975-(k-1)*.145;
    uicontrol(fig,'Style','text','Units','normalized','Position',[.035 y-.035 .93 .03], ...
        'String',headings{k},'FontSize',14,'FontWeight','bold','HorizontalAlignment','left');
    uicontrol(fig,'Style','text','Units','normalized','Position',[.035 y-.135 .93 .095], ...
        'String',bodies{k},'FontSize',11,'HorizontalAlignment','left');
end
uicontrol(fig,'Style','pushbutton','Units','normalized','Position',[.035 .018 .63 .05], ...
    'String','LightSuite method and original documentation', ...
    'Callback',@(~,~)web('https://lightsuite.readthedocs.io/en/latest/usage_fusi/','-browser'));
uicontrol(fig,'Style','pushbutton','Units','normalized','Position',[.70 .018 .265 .05], ...
    'String','Close instructions','Callback',@(~,~)delete(fig));
fusiLightSuiteStyle(fig);
end
